<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Policies\AuthPolicy;use App\Services\ProductNavigationService;use App\Services\RectificationService;use App\Services\TournamentOperationService;use App\Support\Database;use App\Support\Security;use App\Support\Session;use App\Support\View;
final class MatchWorkspaceController {private function row(int$id):array{$s=Database::connection()->prepare('SELECT m.*,t.name tournament_name,t.slug,h.name home_name,a.name away_name,st.name stage_name,g.name group_name,r.name round_name FROM matches m JOIN tournaments t ON t.id=m.tournament_id JOIN teams h ON h.id=m.home_team_id JOIN teams a ON a.id=m.away_team_id LEFT JOIN stages st ON st.id=m.stage_id LEFT JOIN groups_competition g ON g.id=m.group_id LEFT JOIN rounds r ON r.id=m.round_id WHERE m.id=? AND m.deleted_at IS NULL');$s->execute([$id]);return$s->fetch()?:throw new \RuntimeException('Partida nao encontrada.');}public function page(array$p):string{$id=(int)$p['match'];$mode=$p['mode']??'detalhe';$permission=$mode==='operar'?'operate_match':'view';$u=AuthPolicy::requirePermission($permission,'matches',$id);$m=$this->row($id);$db=Database::connection();$q=$db->prepare('SELECT l.*,p.full_name,pp.primary_position FROM match_lineups l JOIN people p ON p.id=l.person_id LEFT JOIN person_profiles pp ON pp.person_id=p.id WHERE l.match_id=? AND l.deleted_at IS NULL');$q->execute([$id]);$lineups=$q->fetchAll();$q=$db->prepare('SELECT e.*,p.full_name,t.name team_name FROM match_events e LEFT JOIN people p ON p.id=e.person_id LEFT JOIN teams t ON t.id=e.team_id WHERE e.match_id=? AND e.deleted_at IS NULL ORDER BY e.minute,e.id');$q->execute([$id]);$events=$q->fetchAll();$q=$db->prepare('SELECT r.*,u.name requester FROM rectification_requests r LEFT JOIN users u ON u.id=r.requested_by WHERE r.match_id=? AND r.deleted_at IS NULL ORDER BY r.id DESC');$q->execute([$id]);$requests=$q->fetchAll();$players=[];foreach([(int)$m['home_team_id'],(int)$m['away_team_id']]as$team){$s=$db->prepare('SELECT p.id,p.full_name,pp.primary_position,r.shirt_number FROM registrations r JOIN people p ON p.id=r.person_id LEFT JOIN person_profiles pp ON pp.person_id=p.id WHERE r.tournament_id=? AND r.team_id=? AND r.status="approved" AND r.deleted_at IS NULL');$s->execute([(int)$m['tournament_id'],$team]);$players[$team]=$s->fetchAll();}return View::render('admin/match-workspace',['title'=>'Partida','user'=>$u,'match'=>$m,'mode'=>$mode,'players'=>$players,'lineups'=>$lineups,'events'=>$events,'requests'=>$requests,'csrf'=>Security::csrfToken()]);}public function action(array$p):never{$id=(int)$p['match'];$u=AuthPolicy::requirePermission((($_POST['action']??'')==='homologate')?'homologate_match':'operate_match','matches',$id);try{Security::verifyCsrf($_POST['_csrf']??null);}catch(\RuntimeException){http_response_code(403);exit('Solicitacao invalida.');}$s=new TournamentOperationService(Database::connection());try{$a=$_POST['action']??'';if($a==='event')$s->event($id,['event_type'=>$_POST['event_type'],'team_id'=>(int)$_POST['team_id'],'person_id'=>(int)($_POST['person_id']??0)?:null,'assist_person_id'=>(int)($_POST['assist_person_id']??0)?:null,'minute'=>(int)($_POST['minute']??0)?:null,'period'=>$_POST['period']??'first'],(int)$u['id']);elseif($a==='finish')$s->finish($id);elseif($a==='homologate')$s->homologate($id,(int)$u['id']);elseif($a==='rectify')(new RectificationService(Database::connection()))->request($id,trim((string)$_POST['reason']),(int)$u['id']);else throw new \RuntimeException('Acao invalida.');Session::flash('success','Operacao registrada.');}catch(\Throwable$e){Session::flash('error',$e->getMessage());}Security::redirect('/admin/partidas/'.$id.'/'.(($p['mode']??'operar')));}}
